"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[8130],{77735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"c792-hdmi-csi-converter","metadata":{"permalink":"/blog/c792-hdmi-csi-converter","source":"@site/blog/2025-08-02-C792-is-Coming.md","title":"C792 HDMI-to-CSI Converter: Bridging 4K Input to 1080p@60Hz Output","description":"The C792 HDMI-to-CSI-2 converter module is now available! This specialized converter designed for Raspberry Pi and Jetson platforms can transform 4K@60Hz HDMI input signals into 1080p@60Hz CSI-2 output, providing the perfect solution for your embedded video projects","date":"2025-08-02T00:00:00.000Z","tags":[{"inline":false,"label":"C792","permalink":"/blog/tags/c792","description":"C792 HDMI to CSI-2 converter module"},{"inline":false,"label":"HDMI-To-CSI","permalink":"/blog/tags/hdmi-to-csi","description":"HDMI to CSI-2 interface conversion technology"},{"inline":false,"label":"Raspberry Pi","permalink":"/blog/tags/raspberry-pi","description":"Raspberry Pi related content and tutorials"},{"inline":false,"label":"Video Capture","permalink":"/blog/tags/video-capture","description":"Video capture and processing technology"}],"readingTime":1.25,"hasTruncateMarker":true,"authors":[{"name":"BliKVM","title":"BliKVM Developer","url":"https://github.com/blikvm","page":{"permalink":"/blog/authors/blikvm"},"socials":{"github":"https://github.com/Thomas"},"imageURL":"https://avatars.githubusercontent.com/u/45224459?v=4","key":"blikvm"}],"frontMatter":{"slug":"c792-hdmi-csi-converter","title":"C792 HDMI-to-CSI Converter: Bridging 4K Input to 1080p@60Hz Output","authors":["blikvm"],"tags":["c792","hdmi-to-csi","raspberry-pi","video-capture"]},"unlisted":false},"content":"The C792 HDMI-to-CSI-2 converter module is now available! This specialized converter designed for Raspberry Pi and Jetson platforms can transform 4K@60Hz HDMI input signals into 1080p@60Hz CSI-2 output, providing the perfect solution for your embedded video projects\\nwith I2S audio capture.\\n\\n\x3c!-- truncate --\x3e\\n\\n![c792](/img/product/C792/C792-4.png)\\n\\n## \ud83c\udfaf Key Features\\n\\n- **4K Input Support**: Up to 4K@60Hz HDMI input capability\\n- **Dual Output**: Simultaneous HDMI loop-out and CSI-2 conversion output\\n- **Audio Support**: I2S digital audio capture\\n- **Wide Compatibility**: Perfect support for Raspberry Pi series and Jetson platforms\\n- **Plug & Play**: No complex configuration required, quick setup\\n\\n## \ud83d\udd0c Interface Configuration\\n\\nC792 provides two CSI-2 interfaces for different hardware:\\n\\n- **15-pin FPC**: 2-lane, suitable for Raspberry Pi Zero/3B/4B\\n- **22-pin FPC**: 4-lane, suitable for Raspberry Pi CM4/5B and Jetson series\\n\\nBesides, the I2S interface is also provided for audio capture.\\n\\n| ![c792-interface](/img/product/C792/C792-front-interface-en.png) | ![c792-interface1](/img/product/C792/C792-back-interface-en.png) |\\n| --- | --- |\\n\\n\\n## \ud83d\ude80 Application Scenarios\\n\\n- **Media Centers**: Game console/set-top box video capture\\n- **Industrial Monitoring**: 1080p@60Hz video capture from manufacturing equipment\\n- **AI Development**: Computer vision projects on Jetson platform\\n\\nBy the way, the C792 is originally designed for Raspberry Pi with proper mounting holes and screws.\\n\\n![c792&Pi](/img/product/C792/C792&Pi-2.png)\\n\\nAnd here is a typical user case:\\n- You can use the C792 to capture the video output from a PC, loop it through to a local monitor, and convert the HDMI signal into a CSI signal for direct use with Raspberry Pi or other devices.\\n\\n![c792-user-case](/img/product/C792/C792-UserCase.png)  \\n\\n\ud83d\udc49 [View Complete Documentation](/docs/device-guides/C792)"}]}}')}}]);